// Dust gauge: measured haze next to assumed grime.
// Left scale: the clear-season dust optical depth at Jezero, MY36
// [jezero.dust.optical_depth_background_my36], read with fact() and turned into
// the fraction of an overhead sunbeam that passes the haze, exp(-tau).
// That is plain attenuation physics: no diffuse skylight, sun straight overhead.
// Right scale: grime on a sample panel. Each sol it grows by
// SETTLE_PER_SOL_PER_TAU * tau. The rate is the PLAYER'S ASSUMPTION, not a fact:
// the index has no dust settling rate. Grime persists in mem slot 0, so a v2
// with a different rate inherits the dirt already on the panel.
import { read, fact, fact_tier, spawn, pose, state_set, signal_emit, log, mem_get, mem_set,
         ENV_LOCAL_HOUR, SHAPE_CYLINDER, SHAPE_PANEL, SHAPE_SPHERE,
         FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36 } from "./host";

// PLAYER'S ASSUMPTION (placeholder, tune freely): grime cover added per sol per unit optical depth.
const SETTLE_PER_SOL_PER_TAU: f32 = 0.002;

const MEM_GRIME: i32 = 0;      // grime cover 0..1, survives reload
const MEM_SOLS: i32 = 1;       // sols elapsed, survives reload
const SIG_HAZE: i32 = 210;
const SIG_GRIME: i32 = 211;
const LOG_TIER: i32 = 1;       // value: provenance tier of the optical-depth fact
const LOG_TAU: i32 = 2;        // value: optical depth read at init
const LOG_SOL_GRIME: i32 = 3;  // value: grime cover at each new whole sol

let tau: f32 = 0.0;
let haze: f32 = 1.0;           // fraction of overhead sunbeam through the haze
let grime: f32 = 0.0;
let sols: f32 = 0.0;
let lastHour: f32 = -1.0;
let lastWholeSol: i32 = 0;
let grimeMark: i32 = -1;

export function init(): void {
  tau = fact(FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36);
  if (tau != tau) tau = 0.0;                     // NaN guard: unknown key reads as no haze
  haze = Mathf.exp(-tau);
  grime = mem_get(MEM_GRIME);
  sols = mem_get(MEM_SOLS);
  lastWholeSol = <i32>Mathf.floor(sols);

  const post = spawn(SHAPE_CYLINDER, 0.08, 1.4, 0.08, 0.7, 0.7, 0.7);
  pose(post, 0.0, 0.7, 0.0, 0.0, 0.0);
  const panel = spawn(SHAPE_PANEL, 0.8, 0.5, 0.03, 0.1, 0.15, 0.4);   // the sample panel
  pose(panel, 0.0, 1.5, 0.0, 0.0, 0.4);
  const hazeScale = spawn(SHAPE_PANEL, 0.1, 1.0, 0.02, 0.85, 0.65, 0.45);
  pose(hazeScale, -0.6, 0.5, 0.0, 0.0, 0.0);
  const grimeScale = spawn(SHAPE_PANEL, 0.1, 1.0, 0.02, 0.45, 0.3, 0.2);
  pose(grimeScale, 0.6, 0.5, 0.0, 0.0, 0.0);
  const hazeMark = spawn(SHAPE_SPHERE, 0.15, 0.15, 0.15, 1.0, 0.9, 0.5);
  pose(hazeMark, -0.6, haze, 0.0, 0.0, 0.0);     // height = fraction of light, 1 m = full sun
  grimeMark = spawn(SHAPE_SPHERE, 0.15, 0.15, 0.15, 0.6, 0.4, 0.2);

  log(LOG_TIER, <f32>fact_tier(FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36));
  log(LOG_TAU, tau);
}

export function tick(dt: f32): void {
  const hour = read(ENV_LOCAL_HOUR);
  if (lastHour >= 0.0) {
    let dh = hour - lastHour;
    if (dh < 0.0) dh += 24.0;                    // crossed midnight
    const dSol: f32 = dh / 24.0;
    sols += dSol;
    grime += SETTLE_PER_SOL_PER_TAU * tau * dSol; // assumed: settling proportional to haze
    if (grime > 1.0) grime = 1.0;
  }
  lastHour = hour;

  const through: f32 = 1.0 - grime;              // assumed: covered fraction blocks its share of light
  pose(grimeMark, 0.6, through, 0.0, 0.0, 0.0);

  const whole = <i32>Mathf.floor(sols);
  if (whole != lastWholeSol) {
    lastWholeSol = whole;
    log(LOG_SOL_GRIME, grime);
  }

  mem_set(MEM_GRIME, grime);
  mem_set(MEM_SOLS, sols);
  state_set(0, tau);
  state_set(1, haze);
  state_set(2, grime);
  state_set(3, through);
  state_set(4, sols);
  state_set(5, SETTLE_PER_SOL_PER_TAU);
  signal_emit(SIG_HAZE, haze);
  signal_emit(SIG_GRIME, grime);
}

